html:
{# Product Information Sheet — wkhtmltopdf-safe table layout #}
{% macro v(val) %}{{ val if val not in (None, '') else '' }}{% endmacro %}
{% macro row2(l1, v1, l2, v2) -%}
<tr>
	<td class="lbl">{{ l1 }}</td>
	<td class="val">{{ v(v1) }}</td>
	<td class="lbl">{{ l2 }}</td>
	<td class="val">{{ v(v2) }}</td>
</tr>
{%- endmacro %}
{% macro row1(l1, v1) -%}
<tr>
	<td class="lbl">{{ l1 }}</td>
	<td class="val" colspan="3">{{ v(v1) }}</td>
</tr>
{%- endmacro %}
{% macro cols() -%}
<colgroup>
	<col class="c1" width="26%">
	<col class="c2" width="25%">
	<col class="c3" width="26%">
	<col class="c4" width="23%">
</colgroup>
{%- endmacro %}
{% macro abs_img(path) -%}
{%- if path -%}
{%- if path.startswith('http') -%}{{ path }}
{%- else -%}{{ frappe.utils.get_url(path) }}
{%- endif -%}
{%- endif -%}
{%- endmacro %}

<div class="pis">
	{% set company_logo = frappe.db.get_value("Letter Head", {"is_default": 1}, "image") or "/files/512x512.jpg" %}
	<table class="pis-header-table">
		<tr>
			<td class="pis-logo-cell">
				<img class="pis-logo" src="{{ abs_img(company_logo) }}" alt="Company Logo" width="70" height="70">
			</td>
			<td class="pis-brand">
				<div class="pis-company">AB Rydéns</div>
				<div>Södergatan, box 138</div>
				<div>S-335 23 Gnosjö, Sweden</div>
				<div>Fax +46 370 33 30 50, Tel +46 370 33 30 40</div>
			</td>
		</tr>
	</table>

	<div class="pis-title">PRODUCT INFORMATION SHEET</div>

	<table class="pis-top" width="100%">
		<tr>
			<td class="pis-flush">
				<table class="pis-table pis-grid">
					{{ cols() }}
					{{ row2("Version:", doc.version, "Last update:", frappe.format(doc.last_update, {'fieldtype':'Date'}) if doc.last_update else '') }}
				</table>
			</td>
		</tr>
		<tr>
			<td class="pis-flush">
				<div class="pis-section-title pis-gi-title">General information</div>
			</td>
		</tr>
		<tr>
			<td class="pis-flush">
				{% set supplier_name = frappe.db.get_value("Partner", doc.supplier, "partner_name") if doc.supplier else "" %}
				<table class="pis-table pis-gi-block" width="100%">
					<colgroup>
						<col class="c1" width="26%">
						<col class="c2" width="50%">
						<col class="c3" width="24%">
					</colgroup>
					<tr>
						<td class="lbl">Supplier:</td>
						<td class="val">{{ v(supplier_name or doc.supplier) }}</td>
						<td class="pis-photo-cell" rowspan="7">
							{% if doc.product_image %}
							{% set photo = fit_print_image(doc.product_image) %}
							<img class="pis-photo" src="{{ abs_img(doc.product_image) }}" alt="Product"
								style="width: {{ photo.width_mm }}mm !important; height: {{ photo.height_mm }}mm !important;">
							{% else %}
							<div class="pis-photo-placeholder">Product photo</div>
							{% endif %}
						</td>
					</tr>
					<tr>
						<td class="lbl">Article no.:</td>
						<td class="val">{{ v(doc.rydens_model_no) }}</td>
					</tr>
					<tr>
						<td class="lbl">Article name:</td>
						<td class="val">{{ v(doc.rydens_model_name) }}</td>
					</tr>
					<tr>
						<td class="lbl">Customer:</td>
						<td class="val">{{ v(doc.customer) }}</td>
					</tr>
					<tr>
						<td class="lbl">Supplier item no.:</td>
						<td class="val">{{ v(doc.supplier_item_no) }}</td>
					</tr>
					<tr>
						<td class="lbl">Sample item no.:</td>
						<td class="val">{{ v(doc.sample_item_no) }}</td>
					</tr>
					<tr>
						<td class="lbl">Category:</td>
						<td class="val">{{ v(doc.description) }}</td>
					</tr>
				</table>
			</td>
		</tr>
	</table>

	<div class="pis-section-title">Specification</div>
	<table class="pis-table pis-grid">
		{{ cols() }}
		{{ row1("Size:", doc.size) }}
		{{ row1("Material and finish:", doc.material_and_finish) }}
		{{ row1("Shade size:", doc.shade_size) }}
		{{ row1("Shade material and finish:", doc.shade_material_and_finish) }}
		{{ row1("Sewed label on shade:", doc.sewed_label_on_shade) }}
		{{ row2("Shade Pantone:", doc.shade_pantone, "Shade inside color:", doc.shade_inside_color) }}
		{{ row2("No. of lampholder:", doc.no_of_lampholder, "Socket type:", doc.socket_type) }}
		{{ row2("Lampholder cup:", doc.lampholder_cup, "Lampholder type:", doc.lampholder_type) }}
		{{ row2("Lampholder color:", doc.lampholder_color, "Lampholdercup color:", doc.lampholdercup_color) }}
		{{ row2("Ceiling hook system:", doc.ceiling_hook_system, "Max. wattage:", doc.max_wattage) }}
		{{ row2("Visible cable length:", doc.visible_cable_length, "Bulb included:", doc.bulb_included) }}
		{{ row2("Visible suspension length:", doc.visible_suspension_length, "Bulb voltage:", doc.bulb_voltage) }}
		{{ row2("Cable color:", doc.cable_color, "Cable type:", doc.cable_type) }}
		{{ row2("Switch/dimmer color:", doc.switch_dimmer_color, "Switch type:", doc.switch_type) }}
		{{ row2("Switch/dimmer position:", doc.switch_dimmer_position, "Plug type:", doc.plug_type) }}
		{{ row2("Dimmer/driver range:", doc.dimmer_driver_range, "Dimmer/Driver brand:", doc.dimmer_driver_brand) }}
		{{ row2("Tilt test:", doc.tilt_test, "Fuse:", doc.fuse) }}
		{{ row2("Suspension method:", doc.suspension_method, "Canopy color:", doc.canopy_color) }}
		{{ row2("Instruction manual:", doc.instruction_manual, "Classification:", doc.classification) }}
	</table>

	<div class="pis-section-title">
		{% if doc.model_use_led == 'Yes' %}Model use LED{% else %}No LED{% endif %}
	</div>
	{% if doc.model_use_led == 'Yes' %}
	<table class="pis-table pis-grid">
		{{ cols() }}
		{{ row2("Number of LED module:", doc.number_of_led_module, "LED chip current (mA):", doc.led_chip_current_ma) }}
		{{ row2("LED in each module:", doc.number_of_led_in_each_module, "LED chip voltage (V):", doc.led_chip_voltage_v) }}
		{{ row2("Color temperature (K):", doc.color_temperature_kelvin, "Luminous Flux (lm):", doc.luminous_flux_lm) }}
		{{ row2("Total Power (W):", doc.total_power_w, "Power Factor:", doc.power_factor) }}
		{{ row2("CRI:", doc.color_rendering_index_cri, "Energy Class:", doc.energy_class) }}
		{{ row2("LED life time (hour):", doc.life_time_of_led_hour, "Beam angle:", doc.beam_angle) }}
		{{ row2("LED driver life (hour):", doc.life_time_of_led_driver_hour, "SDCM:", doc.sdcm) }}
	</table>
	{% endif %}

	<div class="pis-section-title">RoHS document relevant code</div>
	<table class="pis-table">
		{% set printed = [] %}
		{% for row in doc.rohs or [] %}
		{% set code = row.rohs_document_relevant_code %}
		{% if code and code not in printed %}
		<tr>
			<td class="val" colspan="4">{{ v(code) }}</td>
		</tr>
		{% set _ = printed.append(code) %}
		{% endif %}
		{% endfor %}
		{% if not printed %}
		<tr>
			<td class="val" colspan="4">&nbsp;</td>
		</tr>
		{% endif %}
	</table>

	<div class="pis-section-title">Additional information</div>
	<div class="pis-block">{{ v(doc.additional_information) or '—' }}</div>

	<div class="pis-section-title">Label information</div>
	<table class="pis-table pis-grid">
		{{ cols() }}
		<tr>
			<td class="lbl">Product label:</td>
			<td class="val">
				{% if doc.product_label_image %}
				<img class="pis-label-img" src="{{ abs_img(doc.product_label_image) }}" alt="Product label">
				{% endif %}
			</td>
			<td class="lbl">Designer label:</td>
			<td class="val">
				{% if doc.designer_label_image %}
				<img class="pis-label-img" src="{{ abs_img(doc.designer_label_image) }}" alt="Designer label">
				{% endif %}
			</td>
		</tr>
		{{ row2("Product position:", doc.product_label_position, "Designer position:", doc.designer_label_position) }}
		{{ row2("Product size:", doc.product_label_size, "Designer size:", doc.designer_label_size) }}
		{{ row2("Product color:", doc.product_label_color, "Designer color:", doc.designer_label_color) }}
		<tr>
			<td class="lbl">Wattage label:</td>
			<td class="val">
				{% if doc.wattage_label_image %}
				<img class="pis-label-img" src="{{ abs_img(doc.wattage_label_image) }}" alt="Wattage label">
				{% endif %}
			</td>
			<td class="lbl">Energy label:</td>
			<td class="val">
				{% if doc.energy_label_image %}
				<img class="pis-label-img" src="{{ abs_img(doc.energy_label_image) }}" alt="Energy label">
				{% endif %}
			</td>
		</tr>
		{{ row2("Wattage position:", doc.wattage_label_position, "Energy position:", doc.energy_label_position) }}
		{{ row2("Wattage size:", doc.wattage_label_size, "Energy size:", doc.energy_label_size) }}
		{{ row2("Wattage color:", doc.wattage_label_color, "Energy color:", doc.energy_label_color) }}
	</table>

	{% if doc.comments %}
	{% for page_start in range(0, doc.comments|length, 2) %}
	<div class="pis-comments-page{% if page_start + 2 >= doc.comments|length %} pis-comments-page-last{% endif %}">
		<div class="pis-section-title">Comment for the product</div>
		{% for c in doc.comments[page_start:page_start + 2] %}
		<div class="pis-comment-card">
			<div class="pis-comment-no">{{ c.comment_no or (page_start + loop.index) }}</div>
			<div><b>Comment:</b> {{ v(c.comment) }}
				{% if c.comment_date %}<span class="pis-date">({{ frappe.format(c.comment_date, {'fieldtype':'Date'}) }})</span>{% endif %}
			</div>
			<div><b>Supplier reply:</b> {{ v(c.supplier_reply) }}
				{% if c.supplier_reply_date %}<span class="pis-date">({{ frappe.format(c.supplier_reply_date, {'fieldtype':'Date'}) }})</span>{% endif %}
			</div>
			{% if c.attachment %}
			<table class="pis-comment-img-box">
				<tr>
					<td>
						<img class="pis-comment-img" src="{{ abs_img(c.attachment) }}" alt="Comment photo">
					</td>
				</tr>
			</table>
			{% endif %}
		</div>
		{% endfor %}
	</div>
	{% endfor %}
	{% else %}
	<div class="pis-section-title">Comment for the product</div>
	<div class="pis-block">—</div>
	{% endif %}

	<div class="pis-packing">
	<div class="pis-section-title">Packing information</div>
	<table class="pis-table pis-grid">
		{{ cols() }}
		{% set packing_method_display = doc.packing_method_custom if doc.packing_method == 'Others' else doc.packing_method %}
		{% set hangtag_display = doc.hangtag_custom if doc.hangtag == 'Others' else doc.hangtag %}
		{{ row1("Packing method:", packing_method_display) }}
		{{ row1("Hangtag:", hangtag_display) }}
		{{ row1("Droptest:", doc.droptest) }}
		<tr>
			<td class="lbl">Inner box size:</td>
			<td class="val" colspan="3">
				{{ v(doc.inner_box_length_cm) }} cm x {{ v(doc.inner_box_width_cm) }} cm x {{ v(doc.inner_box_height_cm) }} cm
				&nbsp;&nbsp;{{ v(doc.inner_box_volume_m3) }} m3
			</td>
		</tr>
		<tr>
			<td class="lbl">Middle box size:</td>
			<td class="val" colspan="3">
				{{ v(doc.middle_box_length_cm) }} cm x {{ v(doc.middle_box_width_cm) }} cm x {{ v(doc.middle_box_height_cm) }} cm
				&nbsp;&nbsp;{{ v(doc.middle_box_volume_m3) }} m3
			</td>
		</tr>
		<tr>
			<td class="lbl">Outer carton size:</td>
			<td class="val" colspan="3">
				{{ v(doc.outer_carton_length_cm) }} cm x {{ v(doc.outer_carton_width_cm) }} cm x {{ v(doc.outer_carton_height_cm) }} cm
				&nbsp;&nbsp;{{ v(doc.outer_carton_volume_m3) }} m3
			</td>
		</tr>
		{{ row2("Net weight:", (doc.net_weight_kg|string + ' KG') if doc.net_weight_kg not in (None, '') else '', "EAN:", doc.ean) }}
		{{ row2("Inner box gross weight:", (doc.inner_box_gross_weight_kg|string + ' KG') if doc.inner_box_gross_weight_kg not in (None, '') else '', "Quantity/inner box:", (doc.quantity_inner_box|string + ' PCS') if doc.quantity_inner_box not in (None, '') else '') }}
		{{ row2("Middle box gross weight:", (doc.middle_box_gross_weight_kg|string + ' KG') if doc.middle_box_gross_weight_kg not in (None, '') else '', "Quantity/middle box:", (doc.quantity_middle_box|string + ' PCS') if doc.quantity_middle_box not in (None, '') else '') }}
		{{ row2("Outer carton gross weight:", (doc.outer_carton_gross_weight_kg|string + ' KG') if doc.outer_carton_gross_weight_kg not in (None, '') else '', "Quantity/outer carton:", (doc.quantity_outer_carton|string + ' PCS') if doc.quantity_outer_carton not in (None, '') else '') }}
		{{ row2("Show BY RYDENS on shipping mark:", doc.show_by_rydens_on_shipping_mark, "Qty/20':", (doc.qty_20|string + ' PCS') if doc.qty_20 not in (None, '') else '') }}
	</table>
	</div>

	{% if doc.support_files %}
	<div class="pis-section-title">Additional support files</div>
	<table class="pis-table">
		<tr><td class="lbl">Description</td><td class="lbl" colspan="3">File</td></tr>
		{% for f in doc.support_files %}
		<tr>
			<td class="val">{{ v(f.description) }}</td>
			<td class="val" colspan="3">{{ v(f.attach_file) }}</td>
		</tr>
		{% endfor %}
	</table>
	{% endif %}

	<div class="pis-section-title">Version control</div>
	<table class="pis-table">
		<tr>
			<td class="lbl">Version</td>
			<td class="lbl" colspan="2">Comment</td>
			<td class="lbl">Date</td>
		</tr>
		{% if doc.version_control %}
		{% for r in doc.version_control %}
		<tr>
			<td class="val">{{ v(r.version) }}</td>
			<td class="val" colspan="2">{{ v(r.comment) }}</td>
			<td class="val">{{ frappe.format(r.date, {'fieldtype':'Date'}) if r.date else '' }}</td>
		</tr>
		{% endfor %}
		{% else %}
		<tr>
			<td class="val">&nbsp;</td>
			<td class="val" colspan="2">&nbsp;</td>
			<td class="val">&nbsp;</td>
		</tr>
		{% endif %}
	</table>

</div>

css:
/* wkhtmltopdf-safe: tables only, no flex/grid */
.pis {
	font-family: Arial, Helvetica, sans-serif;
	font-size: 9pt;
	color: #000;
	line-height: 1.25;
	width: 100%;
	margin: 0;
	text-align: left;
}
.pis, .pis * {
	overflow-wrap: break-word;
	word-break: normal;
}
.pis-header-table {
	width: 100%;
	border-collapse: collapse;
	margin-bottom: 6px;
}
.print-format .pis-header-table td {
	border: none !important;
	vertical-align: middle;
	padding: 0 !important;
}
.pis-company {
	font-weight: bold;
	font-size: 12pt;
}
.print-format td.pis-logo-cell {
	width: 78px !important;
	max-width: 78px !important;
	padding: 0 8px 0 0 !important;
	vertical-align: middle !important;
}
.print-format td.pis-logo-cell img.pis-logo {
	width: 70px !important;
	height: 70px !important;
	max-width: 70px !important;
	max-height: 70px !important;
}
.pis-brand {
	width: auto;
	font-size: 8pt;
}
.pis-title {
	text-align: center;
	font-size: 14pt;
	font-weight: bold;
	border-top: 2px solid #000;
	border-bottom: 2px solid #000;
	padding: 4px 0;
	margin: 6px 0 8px;
}
.pis-section-title {
	background: #d9d9d9;
	font-weight: bold;
	font-size: 10pt;
	padding: 3px 6px;
	margin-top: 10px;
	margin-bottom: 4px;
	border: 1px solid #000;
	text-align: left;
}
.pis-table {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
	margin: 0;
	text-align: left;
}
.print-format .pis-table td {
	border: 1px solid #666;
	padding: 2px 5px !important;
	vertical-align: top;
	text-align: left;
	word-break: normal;
	overflow-wrap: break-word;
}
.pis-table .lbl {
	width: 22%;
	background: #f3f3f3;
	font-weight: bold;
	text-align: left;
}
.pis-table .val {
	width: 28%;
	text-align: left;
}
.print-format .pis-grid col.c1 { width: 26% !important; }
.print-format .pis-grid col.c2 { width: 25% !important; }
.print-format .pis-grid col.c3 { width: 26% !important; }
.print-format .pis-grid col.c4 { width: 23% !important; }
.print-format .pis-gi-block col.c1 { width: 26% !important; }
.print-format .pis-gi-block col.c2 { width: 50% !important; }
.print-format .pis-gi-block col.c3 { width: 24% !important; }
.print-format .pis-grid td.lbl,
.print-format .pis-grid td.val,
.print-format .pis-gi-block td.lbl,
.print-format .pis-gi-block td.val {
	width: auto;
}
.print-format {
	/* Top padding only affects page 1. wkhtmltopdf margin-top applies to every page. */
	padding: 0 8mm 8mm 8mm !important;
	display: block !important;
	margin-top: 10mm;
}
.pis-top {
	width: 100%;
	border-collapse: collapse;
	border-spacing: 0;
	table-layout: fixed;
	margin: 0;
}
.print-format td.pis-flush {
	border: none !important;
	vertical-align: top;
	padding: 0 !important;
}
.pis-gi-title {
	margin-top: 10px;
	margin-bottom: 4px;
}
.print-format .pis-gi-block td.pis-photo-cell {
	width: 24% !important;
	border: 1px solid #666 !important;
	padding: 3px !important;
	text-align: center;
	vertical-align: middle !important;
	background: #fff;
	box-sizing: border-box;
}
.print-format img.pis-photo,
.print-format td img.pis-photo,
body:last-child .print-format td img.pis-photo {
	max-width: none !important;
	max-height: none !important;
}
.pis-photo-placeholder {
	color: #999;
	padding-top: 60px;
	font-size: 8pt;
	min-height: 120px;
}
.pis-block {
	border: 1px solid #666;
	padding: 6px;
	min-height: 24px;
	white-space: pre-wrap;
}
.pis-label-img {
	max-width: 150px;
	max-height: 90px;
}
.pis-packing {
	page-break-inside: avoid !important;
	break-inside: avoid !important;
	display: block;
	width: 100%;
}
.pis-packing table,
.pis-packing tr {
	page-break-inside: avoid !important;
	break-inside: avoid !important;
}
.pis-comments-page {
	page-break-before: always;
}
.pis-comments-page-last {
	page-break-after: auto;
}
.pis-comments-page-last .pis-comment-card {
	height: auto;
	min-height: 0;
}
.pis-comments-page .pis-section-title {
	margin-top: 0;
	margin-bottom: 0;
}
.pis-comment-card {
	border: 1px solid #666;
	margin: 0 !important;
	padding: 8px;
	height: 112mm;
	overflow: hidden;
	page-break-inside: avoid;
	page-break-after: avoid;
	box-sizing: border-box;
}
.pis-comments-page .pis-section-title + .pis-comment-card {
	border-top: none;
}
.pis-comments-page .pis-comment-card:last-child {
	page-break-after: auto;
}
.pis-comment-no {
	font-weight: bold;
	margin-bottom: 4px;
}
.pis-comment-img-box {
	width: 100%;
	border-collapse: collapse;
	margin-top: 6px;
}
.print-format .pis-comment-img-box td {
	border: none !important;
	padding: 0 !important;
	height: 78mm;
	text-align: center;
	vertical-align: top;
	overflow: hidden;
}
.pis-comment-img {
	max-width: 100%;
	height: 78mm;
	width: auto;
}
.pis-date {
	color: #555;
	font-size: 8pt;
}
.pis-page-number {
	text-align: center;
	font-size: 9pt;
	font-family: Arial, Helvetica, sans-serif;
	color: #333;
	padding: 2px 0 0;
}
